"""Original finance tools: static explanations, no provider data or legal constants."""
from pathlib import Path
from html import escape as e
import json, shutil
ROOT=Path(__file__).resolve().parent
# field: key, label, initial German value, minimum, maximum, integer
CAP=('capital','Startkapital (€)','10.000',0,100000000,False)
RATE=('rate','Rendite pro Jahr (%)','5',-50,50,False)
YEARS=('years','Laufzeit (Jahre)','20',1,60,True)
PAY=('payment','Monatliche Sparrate (€)','200',0,1000000,False)
TOOLS=[
 dict(slug='sparplan',title='Sparplanrechner',tag='Vermögen aufbauen',icon='↗',intro='Was kann aus deiner monatlichen Sparrate werden? Spiele mit Zeit, Startkapital und einer angenommenen Rendite.',fields=[CAP,PAY,RATE,YEARS],formula='i = (1 + r)^(1/12) − 1; Kₘ = Kₘ₋₁ × (1 + i) + S',explain='r ist die jährliche effektive Rendite als Dezimalzahl, i die daraus abgeleitete Monatsrendite und S die Sparrate. Einzahlung jeweils am Monatsende. Für i = 0 gilt Kₙ = K₀ + n × S.',risk='Die Rendite ist eine frei gewählte Modellannahme, keine Markterwartung. Gleichmäßiger Verlauf, keine Kursschwankungen, Steuern oder Kosten.',gloss=['was-ist-ein-etf','diversifikation']),
 dict(slug='zinseszins',title='Zinseszinsrechner',tag='Zeit wirken lassen',icon='×',intro='Erträge bleiben angelegt und können selbst wieder Erträge erzeugen. Sieh den Unterschied zwischen Startkapital und Endwert.',fields=[CAP,RATE,YEARS],formula='Kₜ = K₀ × (1 + r)^t',explain='K₀ ist dein einmaliges Startkapital, r die effektive Jahresrendite als Dezimalzahl und t die Zahl der Jahre. Keine weiteren Einzahlungen; alle Erträge werden wiederangelegt.',risk='Konstante Modellrendite, ohne Kosten und Steuern. Ein tatsächlicher Anlageverlauf kann deutlich abweichen und Verluste bringen.',gloss=['anleihe','leitzins']),
 dict(slug='etf-kosten',title='ETF-Kostenrechner',tag='Kosten sichtbar machen',icon='≈',intro='Zwei Kostenquoten, dieselbe Bruttorendite: Vergleiche, wie laufende Kosten das Modellvermögen verändern.',fields=[CAP,PAY,RATE,YEARS,('feeA','Kostenquote A pro Jahr (%)','0,5',0,10,False),('feeB','Kostenquote B pro Jahr (%)','0,2',0,10,False)],formula='f = 1 − (1 − TER)^(1/12); Kₘ = Kₘ₋₁ × (1 + i) × (1 − f) + S',explain='Beide Varianten nutzen dieselbe Rendite und Sparrate. Die jährliche Kostenquote wird in einen monatlichen Abzugsfaktor umgerechnet. Differenz: Endwert B minus Endwert A. Negative Differenzen bedeuten einen niedrigeren Endwert bei B.',risk='TER nur als vereinfachter jährlicher Vermögensabzug. Keine Transaktionskosten, Spreads, Tracking Difference oder Steuern. TER ist nicht die Gesamtheit aller Anlagekosten. Kein Produktvergleich.',gloss=['gesamtkostenquote','was-ist-ein-etf']),
 dict(slug='entnahmeplan',title='Entnahmeplanrechner',tag='Vermögen nutzen',icon='↓',intro='Wie lange reicht dein Kapital bei regelmäßigen Entnahmen? Prüfe Restvermögen und eine mögliche Aufzehrung im Modell.',fields=[('capital','Anfangsvermögen (€)','100.000',0,100000000,False),('payment','Monatliche Entnahme (€)','600',0,1000000,False),RATE,YEARS],formula='Kₘ = max(0; Kₘ₋₁ × (1 + i) − E)',explain='Erst wird die Monatsrendite berechnet, danach am Monatsende entnommen. E bleibt nominal konstant. Ist nicht genug vorhanden, wird im letzten Monat nur der Rest ausgezahlt. Nach Aufzehrung erfolgen keine weiteren Auszahlungen.',risk='Keine sichere Entnahmerate: Schwankungen und die Reihenfolge von Gewinnen und Verlusten fehlen. Keine Inflationsanpassung, Kosten oder Steuern.',gloss=['was-bedeutet-volatilitaet','inflation']),
 dict(slug='inflation',title='Inflationsrechner',tag='Kaufkraft verstehen',icon='€',intro='Gleicher Betrag, andere Kaufkraft. Berechne, was ein Geldbetrag bei angenommener Inflation später noch wert ist.',fields=[('capital','Heutiger Betrag (€)','10.000',0,100000000,False),('rate','Inflation pro Jahr (%)','2',-20,50,False),YEARS],formula='Kaufkraft = Betrag ÷ (1 + π)^t; Preisäquivalent = Betrag × (1 + π)^t',explain='π ist die angenommene jährliche Inflation als Dezimalzahl. Kaufkraft wird in heutigen Euro angegeben. Das Preisäquivalent zeigt, welcher künftige Betrag für dieselbe heutige Kaufkraft nötig wäre. Negative Raten bilden Deflation ab.',risk='Die eingestellte Rate ist keine aktuelle Inflationsmessung oder Prognose. Persönliche Ausgaben und Preise können anders steigen.',gloss=['inflation','leitzins']),
 dict(slug='kredit',title='Kreditrechner',tag='Raten durchrechnen',icon='÷',intro='Konstante Monatsrate, Zinsanteil und Tilgungsverlauf für einen vollständig getilgten Modellkredit.',fields=[('capital','Kreditbetrag (€)','25.000',1,100000000,False),('rate','Nominaler Sollzins pro Jahr (%)','5',0,50,False),('years','Vollständige Tilgung in Jahren','5',1,60,True)],formula='i = Sollzins ÷ 12; A = K₀ × i ÷ (1 − (1 + i)^(−n))',explain='Sollzins als Dezimalzahl, n = Jahre × 12. Zahlung am Monatsende. Bei 0 % Zins gilt A = K₀ ÷ n. Die Rate wird ohne Zwischenrundung berechnet. Die letzte Bankrate kann durch Cent-Rundung abweichen.',risk='Kein effektiver Jahreszins und kein Kreditangebot. Keine Gebühren, Versicherungen, Sondertilgungen, Zinswechsel oder Restschuld am Laufzeitende.',gloss=['leitzins','anleihe']),
 dict(slug='rendite',title='Renditerechner',tag='Ergebnisse einordnen',icon='%',intro='Von Anfangswert zu Endwert: Berechne die Gesamtrendite und die durchschnittliche jährliche Wachstumsrate (CAGR).',fields=[('capital','Anfangswert (€)','10.000',1,100000000,False),('end','Endwert (€)','15.000',0,100000000,False),YEARS],formula='Gesamtrendite = Endwert ÷ Anfangswert − 1; CAGR = (Endwert ÷ Anfangswert)^(1/t) − 1',explain='Das Modell gilt nur ohne Einzahlungen und Entnahmen. Die CAGR ist eine geglättete jährliche Rate, kein tatsächlicher Jahresverlauf. Bei Endwert 0 beträgt sie −100 %.',risk='Keine zeit- oder geldgewichtete Rendite bei Zahlungsströmen. Ausschüttungen nur dann erfasst, wenn sie im Endwert enthalten sind. Keine gesonderte Kosten-/Steuerberechnung.',gloss=['was-bedeutet-volatilitaet','was-ist-eine-dividende']),
 dict(slug='dividenden',title='Dividendenrechner',tag='Ausschüttungen planen',icon='+',intro='Welche Brutto-Ausschüttung entspräche einer angenommenen Dividendenrendite? Ein einfacher Überschlag, keine Zusage.',fields=[('capital','Angelegter Betrag (€)','10.000',0,100000000,False),('rate','Brutto-Dividendenrendite (%)','3',0,50,False)],formula='Jahresdividende brutto = Kapital × Dividendenrendite; Monatsdurchschnitt = Jahresdividende ÷ 12',explain='Der Monatswert ist nur ein rechnerischer Durchschnitt. Er ist kein Ausschüttungskalender. Es wird weder Wiederanlage noch Dividendenwachstum unterstellt.',risk='Dividenden können gekürzt oder gestrichen werden. Ausschüttungen sind keine zusätzliche risikofreie Rendite. Keine Netto-Berechnung: Steuern, Freibeträge, Kirchensteuer und Quellensteuer werden nicht modelliert.',gloss=['was-ist-eine-dividende','was-ist-eine-aktie'])
]

SOURCES={
 'interest':('Deutsche Bundesbank: Was sind Zinsen?','https://www.bundesbank.de/de/service/schule-und-bildung/erklaerfilme/was-sind-zinsen--860012','Grundlagen zu Anlage-/Kreditzinsen; Sollzins ist nicht effektiver Jahreszins.'),
 'etf':('Verbraucherzentrale: ETF-Auswahl und Kosten','https://www.verbraucherzentrale.de/wissen/geld-versicherungen/sparen-und-anlegen/etfkauf-auf-diese-kriterien-sollten-sie-bei-der-auswahl-achten-16605','Laufende Kosten, Tracking Difference und Ertragsverwendung.'),
 'inflation':('Europäische Zentralbank: Was ist Inflation?','https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_inflation.de.html','Preisniveau, Kaufkraft und unterschiedliche persönliche Warenkörbe.')
}
def source_html(t):
    keys=['inflation'] if t['slug']=='inflation' else ['etf'] if t['slug'] in ('etf-kosten','dividenden','sparplan','rendite') else ['interest']
    return '<h3>Fachliche Grundlagen &amp; Quellen</h3><ul>'+''.join('<li><a href="'+e(SOURCES[k][1],quote=True)+'" rel="noopener noreferrer">'+e(SOURCES[k][0])+'</a><p>'+e(SOURCES[k][2])+'</p></li>' for k in keys)+'</ul><p>Quellen gelesen am 19.10.2026. Die Formeln sind eigene, vereinfachte Rechenmodelle; keine aktuellen Zinsen, historischen Renditen oder Steuersätze aus den Quellen übernommen.</p>'

def build_calculators(page,urls,out,base):
    for name in ('calculators.css','calculator-math.js','calculators.js'):
        shutil.copyfile(ROOT/name,Path(out)/name)
    assets='<link rel="stylesheet" href="/calculators.css">'
    def cards(tools):
        return '<div class="calc-cards">'+''.join('<a class="calc-card" href="/rechner/%s/"><span class="calc-icon" aria-hidden="true">%s</span><small>%s</small><h2>%s <span aria-hidden="true">↗</span></h2><p>%s</p><b>Jetzt durchrechnen →</b></a>'%(t['slug'],t['icon'],e(t['tag']),e(t['title']),e(t['intro'])) for t in tools)+'</div>'
    disclaimer='<aside class="calc-note"><h2>Ein Modell. Keine Vorhersage.</h2><p>Alle Werte sind frei gewählte Rechenbeispiele, keine aktuellen Marktdaten. Keine Anlage-, Kredit- oder Steuerberatung. Ergebnisse sind nominal, sofern nicht ausdrücklich Kaufkraft angegeben ist. Renditen sind nicht garantiert; Verluste sind möglich. <a href="/risikohinweis/">Mehr zu den Risiken</a>.</p></aside>'
    body=assets+'<main class="calc-wrap"><section class="calc-hero"><div><p class="calc-kicker">FA WERKZEUGE / RECHNER</p><h1>Was wäre, wenn?<br><span>Rechne es durch.</span></h1><p class="calc-lead">Aus einer Zahl wird ein Gefühl für deine Finanzen. Acht Rechner für Sparen, Kosten, Kaufkraft und Kredit. Transparent statt Blackbox.</p><div class="calc-pills"><span>Ohne Anmeldung</span><span>Ohne Anbieterwerbung</span><span>Berechnung im Browser</span></div></div><aside class="calc-hero-art" aria-hidden="true"><svg viewBox="0 0 360 210"><path d="M20 180H340M20 120H340M20 60H340" stroke="currentColor" opacity=".13"/><path d="M20 180Q160 180 330 35L330 180Z" fill="currentColor" opacity=".10"/><path d="M20 180Q160 180 330 35" fill="none" stroke="currentColor" stroke-width="5"/><path d="M20 180L330 110" fill="none" stroke="currentColor" stroke-dasharray="7 7" stroke-width="2"/><circle cx="330" cy="35" r="7" fill="currentColor"/></svg><b>Deine Annahmen.<br>Dein Szenario.</b><span>Illustration, keine Prognose</span></aside></section><section aria-label="Alle Finanzrechner">'+cards(TOOLS)+'</section><section class="calc-info"><h2>Vom Begriff zum eigenen Beispiel</h2><p>Erst die Grundlagen, dann die Zahlen: Im <a href="/glossar/">FA-Glossar</a> findest du Erklärungen zu ETF, Inflation, Dividenden und Risiken. Jeder Rechner zeigt seine Formel und Grenzen. Anbieter-Vergleiche, Produktempfehlungen und Live-Zinsangebote sind nicht enthalten.</p><h2>Deine Zahlen bleiben deine Sache</h2><p>Die Rechner senden Eingaben nicht an einen Rechendienst und legen sie nicht in Cookies oder Browser-Speichern ab. Erst „Szenario-Link erstellen“ schreibt Werte in die URL. Teile nur Beispielwerte: Links können in Verlauf, Serverprotokollen und bei Empfängern sichtbar werden.</p></section>'+disclaimer+'</main>'
    urls.append(page('/rechner/','Finanzrechner: Sparplan, Zinsen, ETF-Kosten & mehr | FA','Acht kostenlose Finanzrechner mit Formeln und Diagrammen. Sparplan, Zinseszins, ETF-Kosten, Entnahme, Inflation, Kredit, Rendite und Dividenden.',body,act='/rechner/',crumbs=[('/rechner/','Rechner')]))
    for t in TOOLS:
        fields=''.join('<div class="calc-field"><label for="calc-%s">%s</label><input id="calc-%s" name="%s" type="text" inputmode="%s" value="%s" autocomplete="off" required aria-describedby="calc-format" data-min="%s" data-max="%s" data-integer="%s"></div>'%(f[0],e(f[1]),f[0],f[0],'numeric' if f[5] else 'decimal',f[2],f[3],f[4],str(f[5]).lower()) for f in t['fields'])
        faq=[('Sind die voreingestellten Zahlen eine Empfehlung?','Nein. Sie zeigen nur, wie der Rechner funktioniert. Wähle eigene Annahmen und prüfe auch ungünstige Szenarien.'),('Wie wird gerechnet?',t['explain']),('Werden meine Eingaben gespeichert?','Nicht vom Rechner. Ein Szenario-Link enthält die Eingaben jedoch in seiner URL. Teile keine persönlichen Finanzdaten. Die sonstigen Datenschutzhinweise der Website gelten weiterhin.')]
        config=json.dumps({'type':t['slug']},ensure_ascii=False)
        body=assets+'<script src="/calculator-math.js" defer></script><script src="/calculators.js" defer></script><main class="calc-wrap" data-calculator=\''+config+'\'><a class="calc-back" href="/rechner/">← Alle Rechner</a><section class="calc-heading"><p class="calc-kicker">'+e(t['tag'])+'</p><h1>'+e(t['title'])+'</h1><p class="calc-lead">'+e(t['intro'])+'</p></section><div class="calc-workspace"><form class="calc-form" id="calc-form"><h2>Deine Annahmen</h2><p id="calc-format">Deutsche Schreibweise: 10.000 oder 10.000,50. Jahre als ganze Zahl. Grenzen stehen bei jedem Feld.</p><noscript><p>Die Berechnung benötigt JavaScript. Formeln und Erklärungen stehen unten. Ohne JavaScript werden keine Eingaben übermittelt.</p></noscript><fieldset id="calc-controls" disabled>'+fields+'<p id="calc-error" role="alert" hidden></p><div class="calc-buttons"><button type="submit">Berechnen</button><button type="reset" class="calc-secondary">Zurücksetzen</button></div><button type="button" id="calc-share" class="calc-secondary">Szenario-Link erstellen</button><p class="calc-private">Berechnung lokal. Keine Speicherung durch den Rechner. Ein Link legt Werte offen.</p><div id="calc-share-box" hidden><label for="calc-link">Link zum Kopieren</label><input id="calc-link" type="text" readonly><p>Nur Beispielwerte teilen. URL kann im Verlauf und in Serverprotokollen stehen.</p></div></fieldset></form><section class="calc-output" aria-label="Rechenergebnis"><p class="calc-kicker">DEIN MODELL, KEIN VERSPRECHEN</p><div id="calc-summary" role="status" aria-live="polite" aria-atomic="true"><p>JavaScript aktivieren und „Berechnen“ wählen, um ein Ergebnis zu sehen.</p></div><figure class="calc-chart" id="calc-chart"></figure><div id="calc-detail"></div></section></div><section class="calc-info"><h2>So rechnet dieses Werkzeug</h2><div class="calc-formula">'+e(t['formula'])+'</div><p>'+e(t['explain'])+'</p><h3>Was das Modell nicht kann</h3><p>'+e(t['risk'])+'</p>'+source_html(t)+'<p>Rechenmodell: FA Redaktion · Version 1 · 19.10.2026 · <a href="/transparenz/">Mit KI-Unterstützung</a></p><h3>Grundlagen zum Nachlesen</h3><p>'+' · '.join('<a href="/glossar/'+g+'/">'+e(g.replace('was-ist-','').replace('-',' ').capitalize())+'</a>' for g in t['gloss'])+'</p></section><section class="calc-info"><h2>Häufige Fragen</h2>'+''.join('<details><summary>'+e(q)+'</summary><p>'+e(a)+'</p></details>' for q,a in faq)+'</section>'+disclaimer+'<section class="calc-related"><h2>Weiterdenken, weiterrechnen</h2>'+cards([x for x in TOOLS if x!=t][:3])+'</section></main>'
        ld=[{'@context':'https://schema.org','@type':'WebPage','name':t['title'],'url':base+'/rechner/'+t['slug']+'/'},{'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in faq]}]
        urls.append(page('/rechner/'+t['slug']+'/',t['title']+' mit Formel & Diagramm | FA',t['intro'],body,ld,act='/rechner/',crumbs=[('/rechner/','Rechner'),('/rechner/'+t['slug']+'/',t['title'])]))
    # Output-only cross-links keep the glossary renderer conflict-free.
    for t in TOOLS:
        for slug in t['gloss']:
            path=Path(out)/'glossar'/slug/'index.html'
            if path.exists():
                text=path.read_text();link='<p class="gl-calculator"><a href="/rechner/%s/">Mit Zahlen verstehen: %s →</a></p>'%(t['slug'],e(t['title']))
                text=text.replace('<section class="gl-caution">',link+'<section class="gl-caution">',1);path.write_text(text)
